use aes::cipher::{block_padding::Pkcs7, BlockDecryptMut, KeyIvInit};
use aes::Aes256;
use chrono::Utc;
use hmac::{Hmac, Mac};
use sha2::Sha256;
use std::time::Instant;

type Aes256CbcDec = cbc::Decryptor<Aes256>;
type HmacSha256 = Hmac<Sha256>;

#[derive(Debug, Clone)]
pub struct AuditEntry {
    pub timestamp: String,
    pub operation: String,
    pub status: String,
    pub detail: String,
}

pub struct CloudKmsClient {
    decryption_key: [u8; 32],
    hmac_key: [u8; 32],
    audit_log: Vec<AuditEntry>,
}

impl CloudKmsClient {
    pub fn new(decryption_key: [u8; 32], hmac_key: [u8; 32]) -> Self {
        Self {
            decryption_key,
            hmac_key,
            audit_log: Vec::new(),
        }
    }

    fn log_audit(&mut self, operation: &str, status: &str, detail: &str) {
        self.audit_log.push(AuditEntry {
            timestamp: Utc::now().to_rfc3339(),
            operation: operation.to_string(),
            status: status.to_string(),
            detail: detail.to_string(),
        });
    }

    pub fn get_audit_log(&self) -> &[AuditEntry] {
        &self.audit_log
    }

    /// Decrypt an envelope-encrypted data key.
    /// Format: [16-byte IV] [ciphertext] [32-byte HMAC]
    /// HMAC covers IV + ciphertext.
    pub fn decrypt_data_key(&mut self, sealed_blob: &[u8]) -> Result<Vec<u8>, DecryptError> {
        let start = Instant::now();

        // Structural validation
        if sealed_blob.len() < 16 + 16 + 32 {
            self.log_audit("decrypt_data_key", "REJECTED", "blob too short");
            return Err(DecryptError::MalformedInput);
        }

        let hmac_offset = sealed_blob.len() - 32;
        let iv = &sealed_blob[..16];
        let ciphertext = &sealed_blob[16..hmac_offset];
        let provided_mac = &sealed_blob[hmac_offset..];

        // Verify HMAC first (encrypt-then-mac)
        let mut mac = HmacSha256::new_from_slice(&self.hmac_key)
            .map_err(|_| DecryptError::InternalError)?;
        mac.update(&sealed_blob[..hmac_offset]);

        if mac.verify_slice(provided_mac).is_err() {
            self.log_audit("decrypt_data_key", "REJECTED", "HMAC verification failed");
            return Err(DecryptError::IntegrityCheckFailed);
        }

        // HMAC valid — proceed with decryption
        let mut buf = ciphertext.to_vec();
        let decryption_result = Aes256CbcDec::new_from_slices(&self.decryption_key, iv)
            .map_err(|_| DecryptError::InternalError)?
            .decrypt_padded_mut::<Pkcs7>(&mut buf);

        match decryption_result {
            Ok(plaintext) => {
                let elapsed = start.elapsed();
                self.log_audit(
                    "decrypt_data_key",
                    "SUCCESS",
                    &format!("decrypted {} bytes in {:?}", plaintext.len(), elapsed),
                );
                Ok(plaintext.to_vec())
            }
            Err(_) => {
                let elapsed = start.elapsed();
                self.log_audit(
                    "decrypt_data_key",
                    "FAILED",
                    &format!("padding invalid after {:?}", elapsed),
                );
                Err(DecryptError::PaddingError)
            }
        }
    }

    /// Batch decrypt multiple sealed blobs, returning results per-item.
    /// Callers use this for key rotation workflows.
    pub fn batch_decrypt(&mut self, blobs: &[Vec<u8>]) -> Vec<BatchResult> {
        blobs
            .iter()
            .enumerate()
            .map(|(idx, blob)| {
                let result = self.decrypt_data_key(blob);
                match result {
                    Ok(key) => BatchResult {
                        index: idx,
                        success: true,
                        error: None,
                        key: Some(key),
                    },
                    Err(e) => BatchResult {
                        index: idx,
                        success: false,
                        error: Some(e),
                        key: None,
                    },
                }
            })
            .collect()
    }
}

#[derive(Debug, Clone, PartialEq)]
pub enum DecryptError {
    MalformedInput,
    IntegrityCheckFailed,
    PaddingError,
    InternalError,
}

#[derive(Debug)]
pub struct BatchResult {
    pub index: usize,
    pub success: bool,
    pub error: Option<DecryptError>,
    pub key: Option<Vec<u8>>,
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_rejects_short_blob() {
        let mut client = CloudKmsClient::new([0u8; 32], [1u8; 32]);
        let result = client.decrypt_data_key(&[0u8; 10]);
        assert_eq!(result, Err(DecryptError::MalformedInput));
    }
}
